// Reuse the same save queue for initial folder restore and subsequent autosaves.
const unifiedOriginalSync=SaveBridge.sync.bind(SaveBridge);
SaveBridge.sync=function(...args){if(this.unifiedPromise)return this.unifiedPromise;this.unifiedPromise=Promise.resolve(unifiedOriginalSync(...args)).finally(()=>{this.unifiedPromise=null;});return this.unifiedPromise;};
SaveBridge.flush=async function(){clearTimeout(this.timer);for(let attempt=0;attempt<4;attempt++){await this.sync();if(this.conflicts)throw Error('Choose which saved versions to keep in Saving status.');if(this.error)throw Error(this.error);if(!this.pending.size&&!this.syncing)return {saved:true};}throw Error('Folder backup is still pending.');};
SaveBridge.flushOnExit=function(){
  if(this.paused||this.conflicts||!LocalBridge.capabilities?.token)return;
  try{ProgressBackup.flush();ClassicSave.persist();LearningTiming.flush();const records={};for(const key of this.pending){const clock=this.clock[key];if(clock&&this.allowed(key))records[key]={...clock,value:this.clean(key,localStorage.getItem(key))};}if(Object.keys(records).length)fetch(new URL('__codelab__/progress',document.baseURI),{method:'POST',keepalive:true,headers:{'Content-Type':'application/json','X-CodeLab-Token':LocalBridge.capabilities.token},body:JSON.stringify({format:1,records})}).catch(()=>{});}catch{}
};
window.addEventListener('pagehide',()=>SaveBridge.flushOnExit());
