const unifiedSettings=UI.openSettings.bind(UI);
UI.openSettings=function(){unifiedSettings();for(const section of document.querySelectorAll('#modal-settings .settings-section'))if(section.textContent.includes('JDoodle'))section.innerHTML='<h3>Offline execution</h3><p style="font-size:12px;color:var(--text-secondary)">Python, JavaScript, SQLite and web previews are included. C/C++ and Java use a local compiler/JDK when installed. This edition does not send code to a cloud compiler.</p>';};
OfflineAccess.open=async function(){if(window.PRATICE_STATIC){window.open('https://github.com/laxtline/Pratice-Code/releases/latest','_blank','noopener');return;}UI.close();let modal=document.getElementById('modal-offline-access');if(!modal){modal=document.createElement('section');modal.id='modal-offline-access';modal.className='modal-overlay';document.body.append(modal);}modal.innerHTML='<div class="modal"><div class="modal-head"><h2>Your offline study website</h2><button class="x-close" onclick="UI.close()" aria-label="Close">×</button></div><div class="modal-body"><p>Courses, practice, tests, books, reference code and the editor engines are included in this folder. You can disconnect the internet. Keep the local launcher running while using the website.</p><div class="academy-actions"><a class="btn-primary" href="/downloads/Pratice-Code-Offline.zip" download>Download complete offline website</a><button class="btn-ghost" onclick="DataIO.exportProgress()">Back up all progress</button><button class="btn-ghost" onclick="DataIO.importProgress()">Restore progress</button><button class="btn-ghost" onclick="SaveBridge.open()">Saving status</button></div><p style="margin-top:15px">To use another computer, extract the full folder and run Install and Start.cmd on Windows, or python3 install.py on macOS/Linux. Python 3.10+ is required; Node.js and npm are not needed.</p><p>C/C++ and Java need a local compiler/JDK. External source links are optional online references.</p></div><div class="modal-foot"><button class="btn-primary" onclick="UI.close()">Done</button></div></div>';modal.classList.add('show');};
